(function(){"use strict";app.factory("menuService",function(n){const t=n.get("mainService"),e="Config/Menu/",u="Config/SubMenu/",r={get:function(n){return t.getData("get",e+"?json="+JSON.stringify(n),null,!0).then(n=>{if("0"===n.code)throw n;if("1"===n.code){let t=JSON.parse(n.payload)||[];return t[0]}})},save:function(n){return t.getData("post",`${e}?json=${JSON.stringify(n)}`,null,!0)},update:function(n,u){return t.getData("put",`${e}${n}?json=${JSON.stringify(u)}`,null,!0)},delete:function(n){return t.getData("delete",e+n,null,!0)},findByIdMenu:function(n){return t.getData("get",u+"FindByIdMenu/"+n,null,!0).then(n=>{if("0"===n.code)throw n;if("1"===n.code){let t=JSON.parse(n.payload)||[];return t}})},saveSubMenu:function(n){return t.getData("post",`${u}?json=${JSON.stringify(n)}`,null,!0)},updateSubMenu:function(n,e){return t.getData("put",`${u}${n}?json=${JSON.stringify(e)}`,null,!0)},deleteSubMenu:function(n){return t.getData("delete",u+n,null,!0)}};return r})})(window.angular);